Chapter: Nine days

The paragraph: In June the share price fell from 104.5 euros to 1.28 euros. Nobody could stop it.

This graphic covers: The share price fell from 104.5 euros to 1.28 euros.
Length: 7.7 s

Words spoken in it, from its start:
0.2 s  Revenue
0.7 s  of
1.2 s  4.2bn,
1.7 s  a
2.2 s  loss
2.7 s  of
3.2 s  900m,
3.7 s  and
4.2 s  12,000
4.7 s  staff
5.2 s  gone.

Intent: Three figures tell the collapse: 4.2bn revenue, a 900m loss, 12,000 staff gone.
Rests on claims: 4

A passing design of this technique (kpi-counter: each figure lands large and counts, then docks into a row above as the next is introduced, the last left large), in this sandbox and on the tokens, for its mechanics, its timing and its standard. It uses: drum, docking, cause to effect. Its concept came from its own narration: find this slot's own rather than reusing its layout. Its words and figures are its own; yours come from this slot and its claims:
````jsx
// Concept: each figure takes the stage, then makes room for the next. A figure lands large
// as it is spoken and counts to its mark; when the narration moves on to the next one it
// shrinks and docks into a row above, so the frame ends with the earlier figures as context
// and the last one, the point, still large.
// Storyboard, on the narration's clock:
//   0.0 s  the hook: the label of the first figure rises in where the figure will land
//   1.2 s  "4.2bn": the figure rises in large and counts to its mark
//   2.2 s  its count landed: the first figure shrinks and docks at the top left, and the next
//          label rises in on the stage once it is clear
//   3.2 s  "900m": the second figure lands large and counts, in the collapse colour
//   3.7 s  before the last figure arrives: it docks beside the first, still counting
//   4.2 s  "12,000": the last figure lands on the hero spring and counts, its label after it
//   to the end: the row and the hero hold while the camera keeps a slow push
// Every figure stays on screen once it has landed; none fades out.
const FIGURES = [
  { cue: '4.2bn', target: 4.2, decimals: 1, suffix: 'bn', label: 'Revenue', labelAfter: false, tone: 'textPrimary' },
  { cue: '900m', target: 900, decimals: 0, suffix: 'm', label: 'Loss', labelAfter: false, tone: 'collapse' },
  { cue: '12,000', target: 12000, decimals: 0, suffix: '', label: 'Staff gone', labelAfter: true, tone: 'collapse' },
]

// When the narration says a word: the first word that starts with cue, else the fallback.
function spokenAt(words, cue, fallbackMs) {
  const said = words.find((word) => word.text.indexOf(cue) === 0)
  return said ? said.atMs : fallbackMs
}

// A number at fixed decimals, its thousands grouped by hand: 12000 is "12,000".
function formatFigure(value, decimals) {
  const parts = value.toFixed(decimals).split('.')
  const whole = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',')
  return whole + (parts.length > 1 ? '.' + parts[1] : '')
}

// Helpers, called directly: 0 to 1 over lengthMs from atMs, held at 1, one per curve,
// since each interpolate names its curve in the call.
function range(fps, atMs, lengthMs) {
  return [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)]
}
function arrive(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.enter, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function travel(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function tally(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.linear, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}

// Motion blur that follows speed: a move of more than a few pixels a frame softens, and
// only while it is moving. moved is how far the element travelled since the last frame.
function blurFor(moved, unit) {
  const px = Math.min(8, Math.abs(moved) / (6 * unit)) * unit
  return px > 0.4 * unit ? 'blur(' + px.toFixed(2) + 'px)' : 'none'
}

// A helper, called directly: where a figure block stands at a frame, between the stage and
// its dock, with its scale.
function placeAt(frame, fps, spec) {
  const docked = spec.dockAt === null ? 0 : travel(frame, fps, spec.dockAt, motion.ms.move)
  return {
    x: spec.stage.x + (spec.dock.x - spec.stage.x) * docked,
    y: spec.stage.y + (spec.dock.y - spec.stage.y) * docked,
    scale: 1 + (spec.dockScale - 1) * docked,
  }
}

// A helper, called directly: one figure with its label, on the stage or docked.
function figureBlock(item, index, spec) {
  const { frame, fps, unit, colors, fonts } = spec
  const timing = spec.timings[index]
  const now = placeAt(frame, fps, { ...timing, stage: spec.stage, dock: spec.docks[index] || spec.stage, dockScale: spec.dockScale })
  const before = placeAt(frame - 1, fps, { ...timing, stage: spec.stage, dock: spec.docks[index] || spec.stage, dockScale: spec.dockScale })
  const hero = index === FIGURES.length - 1
  const pop = hero
    ? Remotion.spring({ frame, fps, delay: motion.frames(timing.figureAt, fps), config: motion.spring.hero })
    : arrive(frame, fps, timing.figureAt, motion.ms.enter)
  const count = tally(frame, fps, timing.figureAt, motion.ms.count)
  const labelIn = arrive(frame, fps, timing.labelAt, motion.ms.enter)
  // Nothing is written before the count starts: a waiting "0" would be a figure on screen.
  const shown = frame >= motion.frames(timing.figureAt, fps) ? formatFigure(item.target * count, item.decimals) + item.suffix : ''
  const tone = item.tone === 'textPrimary' ? colors.textPrimary : colors.semantic[item.tone]
  // The label grows as its block docks, so it still reads at the docked scale.
  const docking = timing.dockAt === null ? 0 : travel(frame, fps, timing.dockAt, motion.ms.move)
  const label = (
    <div style={{ fontFamily: fonts.title, fontSize: 48 * unit * (1 + 0.7 * docking), color: colors.textSecondary, opacity: labelIn, transform: 'translateY(' + (1 - labelIn) * motion.px.rise * unit + 'px)' }}>
      {item.label}
    </div>
  )
  return (
    <div
      key={item.cue}
      style={{
        position: 'absolute', left: now.x, top: now.y, transformOrigin: 'left top',
        transform: 'scale(' + now.scale + ')', whiteSpace: 'nowrap',
        filter: blurFor(Math.hypot(now.x - before.x, now.y - before.y), unit),
      }}
    >
      {item.labelAfter ? null : label}
      <div
        style={{
          fontFamily: fonts.numbers, fontSize: spec.figureSize, lineHeight: 1, color: tone,
          fontVariantNumeric: 'tabular-nums', height: spec.figureSize, opacity: Math.min(1, Math.max(0, pop)),
          transform: 'translateY(' + (1 - pop) * motion.px.rise * 2 * unit + 'px)',
        }}
      >
        {shown}
      </div>
      {item.labelAfter ? label : null}
    </div>
  )
}

function Graphic(props) {
  const frame = Remotion.useCurrentFrame()
  const { width, height, fps } = Remotion.useVideoConfig()
  const { colors, fonts } = props.brand
  const inset = props.safeArea
  const portrait = height > width
  const unit = Math.min(width, height) / 1080
  const room = width - inset.left - inset.right
  const roomH = height - inset.top - inset.bottom

  // Each figure's times: its label lands with the first word after the previous figure (or at
  // the start), the figure on its cue, and it docks when the narration moves past it.
  const timings = FIGURES.map((item, index) => {
    const figureAt = spokenAt(props.words, item.cue, props.durationMs * (0.15 + 0.25 * index))
    const previous = index === 0 ? null : spokenAt(props.words, FIGURES[index - 1].cue, 0)
    const after = previous === null ? null : props.words.find((word) => word.atMs > previous)
    // A label said after its figure ("12,000 staff gone") lands on the word after the figure.
    const following = props.words.find((word) => word.atMs > figureAt)
    const labelAt = item.labelAfter ? (following ? following.atMs : figureAt + motion.ms.count) : after ? after.atMs : 0
    return { figureAt, labelAt, dockAt: null }
  })
  // A figure docks once its count has landed, unless that would leave it on the stage when
  // the next figure arrives; then it docks early enough to clear the stage. The next label
  // waits until the stage is half clear, so two labels never share it.
  timings.forEach((timing, index) => {
    if (index < timings.length - 1) {
      const next = props.words.find((word) => word.atMs > timing.figureAt)
      const landed = Math.max(next ? next.atMs : 0, timing.figureAt + motion.ms.count)
      timing.dockAt = Math.min(landed, timings[index + 1].figureAt - 0.6 * motion.ms.move)
      if (!FIGURES[index + 1].labelAfter) {
        timings[index + 1].labelAt = Math.max(timings[index + 1].labelAt, timing.dockAt + 0.5 * motion.ms.move)
      }
    }
  })

  // Sized from the longest finished figure (about 0.6 em a character), so the hero fits.
  const longest = Math.max(...FIGURES.map((item) => (formatFigure(item.target, item.decimals) + item.suffix).length))
  const figureSize = Math.min((portrait ? 220 : 280) * unit, (0.92 * room) / (longest * 0.6))
  const dockScale = 0.42
  const dockPitch = (longest * 0.6 * figureSize * dockScale) + (portrait ? 48 : 90) * unit
  const docks = FIGURES.slice(0, -1).map((item, index) => ({ x: index * dockPitch, y: roomH * (portrait ? 0.2 : 0.12) }))
  const stage = { x: 0, y: roomH * (portrait ? 0.44 : 0.4) }
  const push = travel(frame, fps, 0, props.durationMs)

  return (
    <Remotion.AbsoluteFill
      style={{
        paddingTop: inset.top, paddingRight: inset.right,
        paddingBottom: inset.bottom, paddingLeft: inset.left,
        transform: 'scale(' + (1 + 0.03 * push) + ')', transformOrigin: inset.left + 'px 50%',
      }}
    >
      <div style={{ position: 'relative', width: room, height: roomH }}>
        {FIGURES.map((item, index) =>
          figureBlock(item, index, { frame, fps, unit, colors, fonts, timings, stage, docks, dockScale, figureSize }),
        )}
      </div>
    </Remotion.AbsoluteFill>
  )
}

````
